UNITS = [{'id': 'PEDS-U319', 'ch': 39, 'n': 1, 'title': 'Neural Tube Defects — Caudal Defects', 'sec': 'Neural tube defects · p175', 'qs': ['PEDS-C39-001', 'PEDS-C39-002', 'PEDS-C39-003', 'PEDS-C39-004', 'PEDS-C39-005', 'PEDS-C39-006', 'PEDS-C39-007', 'PEDS-C39-008', 'PEDS-C39-009', 'PEDS-C39-010', 'PEDS-C39-011', 'PEDS-C39-012', 'PEDS-C39-013', 'PEDS-C39-014', 'PEDS-C39-015', 'PEDS-C39-016', 'PEDS-C39-017', 'PEDS-C39-018', 'PEDS-C39-019', 'PEDS-C39-020', 'PEDS-C39-021', 'PEDS-C39-022', 'PEDS-C39-023', 'PEDS-C39-024', 'PEDS-C39-025', 'PEDS-C39-026', 'PEDS-C39-027'], 'guide': 'NTDs are the commonest congenital CNS malformations. Learn maternal risks, anterior/posterior neuropore timing and the spectrum from occult spina bifida through meningocele to severe myelomeningocele.'}, {'id': 'PEDS-U320', 'ch': 39, 'n': 2, 'title': 'Cranial NTDs, Antenatal Diagnosis & Prevention', 'sec': 'Cranial NTDs and prevention · p176', 'qs': ['PEDS-C39-028', 'PEDS-C39-029', 'PEDS-C39-030', 'PEDS-C39-031', 'PEDS-C39-032', 'PEDS-C39-033', 'PEDS-C39-034', 'PEDS-C39-035', 'PEDS-C39-036', 'PEDS-C39-037', 'PEDS-C39-038', 'PEDS-C39-039', 'PEDS-C39-040', 'PEDS-C39-041', 'PEDS-C39-042', 'PEDS-C39-043', 'PEDS-C39-044', 'PEDS-C39-045', 'PEDS-C39-046', 'PEDS-C39-047', 'PEDS-C39-048', 'PEDS-C39-049'], 'guide': 'Cranial NTDs include lethal anencephaly, occipital encephalocele, iniencephaly and craniorachischisis. Diagnose antenatally by ultrasound and markers; folate before conception markedly lowers risk.'}, {'id': 'PEDS-U321', 'ch': 39, 'n': 3, 'title': 'Neuronal Migration Defects', 'sec': 'Neuronal migration defects · p177', 'qs': ['PEDS-C39-050', 'PEDS-C39-051', 'PEDS-C39-052', 'PEDS-C39-053', 'PEDS-C39-054', 'PEDS-C39-055', 'PEDS-C39-056', 'PEDS-C39-057', 'PEDS-C39-058', 'PEDS-C39-059', 'PEDS-C39-060', 'PEDS-C39-061', 'PEDS-C39-062', 'PEDS-C39-063', 'PEDS-C39-064', 'PEDS-C39-065', 'PEDS-C39-066', 'PEDS-C39-067', 'PEDS-C39-068', 'PEDS-C39-069', 'PEDS-C39-070', 'PEDS-C39-071', 'PEDS-C39-072', 'PEDS-C39-073'], 'guide': 'Migration defects include smooth agyric lissencephaly, cleft-like schizencephaly, white-matter-lined porencephalic cysts, agenesis of corpus callosum/Aicardi syndrome and SHH-related holoprosencephaly.'}, {'id': 'PEDS-U322', 'ch': 39, 'n': 4, 'title': 'Hydrocephalus — Causes & Congenital Anomalies', 'sec': 'Hydrocephalus causes · p178–179', 'qs': ['PEDS-C39-074', 'PEDS-C39-075', 'PEDS-C39-076', 'PEDS-C39-077', 'PEDS-C39-078', 'PEDS-C39-079', 'PEDS-C39-080', 'PEDS-C39-081', 'PEDS-C39-082', 'PEDS-C39-083', 'PEDS-C39-084', 'PEDS-C39-085', 'PEDS-C39-086', 'PEDS-C39-087', 'PEDS-C39-088', 'PEDS-C39-089', 'PEDS-C39-090', 'PEDS-C39-091', 'PEDS-C39-092', 'PEDS-C39-093', 'PEDS-C39-094', 'PEDS-C39-095', 'PEDS-C39-096', 'PEDS-C39-097', 'PEDS-C39-098', 'PEDS-C39-099', 'PEDS-C39-100', 'PEDS-C39-101', 'PEDS-C39-102', 'PEDS-C39-103', 'PEDS-C39-104'], 'guide': 'Hydrocephalus is increased intracranial CSF volume. Separate obstructive causes (especially aqueductal stenosis) from non-obstructive overproduction or impaired absorption, and know Dandy-Walker, Chiari and vein-of-Galen patterns.'}, {'id': 'PEDS-U323', 'ch': 39, 'n': 5, 'title': 'Hydrocephalus — Clinical Features, Investigation & Treatment', 'sec': 'Hydrocephalus management · p180', 'qs': ['PEDS-C39-105', 'PEDS-C39-106', 'PEDS-C39-107', 'PEDS-C39-108', 'PEDS-C39-109', 'PEDS-C39-110', 'PEDS-C39-111', 'PEDS-C39-112', 'PEDS-C39-113', 'PEDS-C39-114', 'PEDS-C39-115', 'PEDS-C39-116', 'PEDS-C39-117', 'PEDS-C39-118', 'PEDS-C39-119', 'PEDS-C39-120', 'PEDS-C39-121', 'PEDS-C39-122', 'PEDS-C39-123'], 'guide': 'Raised CSF volume in infants causes macrocephaly and features of raised ICP, including sunset eyes. Screen with neurosonography, confirm with MRI, reduce CSF medically with acetazolamide or divert it with VP shunt; remember shunt infection.'}]
